#include "runtime/bus.hpp"
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace nes::mods;
static unsigned n{};static void check(bool b,const char* m){if(!b)throw std::runtime_error(m);++n;}
static std::string source(const char* p){std::ifstream f(p);return {std::istreambuf_iterator<char>(f),{}};}
int main(int argc,char**argv){try{
 check(argc==3||argc==7,"two authored Lua sources required");
 LuaMod none("assert(nes==nil)",2*1024*1024,2,0);check(!none.needs_memory(),"no permission captures RAM");
 LuaMod read("assert(nes.memory.observe==nil and nes.memory.write_u8==nil);function on_update() local t=nes.memory.read_range(2046,2);assert(t[1]==7 and t[2]==8);t[1]=9;assert(nes.memory.read_u8(2046)==7)end",2*1024*1024,2,4);
 Observation o;o.memory=MemorySnapshot{};o.memory->bytes[2046]=7;o.memory->bytes[2047]=8;read.update(o);check(read.updates()==1&&o.memory->bytes[2046]==7,"snapshot aliases RAM");
 LuaMod missing("function on_update()assert(nes.memory.read_u8(0)==nil and nes.memory.read_range(0,1)==nil)end",2*1024*1024,2,4);missing.update({});check(missing.updates()==1,"unknown snapshot fabricated");
 LuaMod watch("function on_load()nes.memory.observe(32,2,function(c)assert(#c==2 and c[1].address==32 and c[1].old_value==0 and c[1].new_value==1 and c[2].address==33);c[1].new_value=9;log.info('CHANGED')end)end",2*1024*1024,2,12);watch.load({});watch.update(o);check(watch.logs().empty(),"initial snapshot not baseline");watch.update(o);check(watch.logs().empty(),"unchanged RAM notifies");o.memory->bytes[32]=1;o.memory->bytes[33]=2;watch.update(o);check(watch.logs().size()==1&&o.memory->bytes[32]==1,"ordered delta or detached values invalid");watch.unload();o.memory->bytes[32]=3;watch.update(o);check(watch.logs().size()==1,"unload left observer");
 for(const char* s:{"function on_update()nes.memory.read_u8(-1)end","function on_update()nes.memory.read_u8(2048)end","function on_update()nes.memory.read_u8(8194)end","function on_update()nes.memory.read_u8(16405)end","function on_update()nes.memory.read_u8(32768)end","function on_update()nes.memory.read_u8(0/0)end","function on_update()nes.memory.read_u8('1')end","function on_update()nes.memory.read_u8(0,1)end","function on_update()nes.memory.read_range(0,0)end","function on_update()nes.memory.read_range(0,65)end","function on_update()nes.memory.read_range(2047,2)end","function on_update()nes.memory.observe(0,1,function()end)end","nes.memory.observe(0,1,function()end)","function on_load()nes.memory.observe(0,1,2)end","function on_load()nes.memory.observe(0,2,function()end);nes.memory.observe(1,1,function()end)end","function on_load()for i=0,4 do nes.memory.observe(i,1,function()end)end end","function on_load()for i=0,2 do nes.memory.observe(i*64,64,function()end)end end"}){
  bool bad=false;try{LuaMod m(s,2*1024*1024,2,12);m.load({});m.update(o);}catch(...){bad=true;}check(bad,"unsafe memory argument/quota accepted");
 }
 bool bad=false;try{LuaMod m("",2*1024*1024,2,8);}catch(...){bad=true;}check(bad,"observe without read accepted");
 LuaMod fault("function on_load()nes.memory.observe(0,1,function()error('own fault')end)end",2*1024*1024,2,12);fault.load({});fault.update(o);o.memory->bytes[0]=1;bad=false;try{fault.update(o);}catch(...){bad=true;}check(bad,"observer failure not propagated");fault.update(o);check(fault.updates()==2,"fault left callback registered");
 for(auto program:{"while true do end","local t={};while true do t[#t+1]={} end"}){bad=false;try{LuaMod m(std::string("function on_load()nes.memory.observe(0,1,function()")+program+" end)end",65536,2,12);m.load({});o.memory->bytes[0]=0;m.update(o);o.memory->bytes[0]=1;m.update(o);}catch(...){bad=true;}check(bad,"observer escapes resource budget");}
 std::array<uint8_t,32768> prg{};std::array<uint8_t,8192> chr{};nes::runtime::Bus bus({prg.data(),prg.size(),chr.data(),chr.size()});bus.advance(100);auto cycles=bus.cycles(),audio=bus.audio().cycles(),dots=bus.video().dots();bus.ram().write(3,12);auto snap=capture_memory(bus.ram());check(snap.bytes[3]==12&&bus.cycles()==cycles&&bus.audio().cycles()==audio&&bus.video().dots()==dots,"capture touched devices");
 for(int i=1;i<=2;++i){LuaMod m(source(argv[i]),2*1024*1024,2,i==1?12:14);m.load({});o.memory=MemorySnapshot{};m.update(o);o.memory->bytes[0]=42;o.memory->bytes[256]=8;m.update(o);check(m.logs().size()==(i==1?2:1),"authored example did not observe selected range");check(i==1?m.overlay().empty():m.overlay().size()==3,"second example HUD missing");m.unload();auto count=m.logs().size();o.memory->bytes[0]=8;o.memory->bytes[256]=10;m.update(o);check(m.logs().size()==count,"authored example left observer after unload");}
 if(argc==7){Manager manager(argv[3],argv[4],argv[5],{"0.9.0","addams-family-pal-eu-enfrde"});for(const auto pair:{std::pair<const char*,const char*>{"sdk.ram-change-logger","RAM-Change-Logger-v1.0.zip"},{"sdk.ram-change-counter","RAM-Change-Counter-v1.0.zip"}}){manager.install(std::filesystem::path(argv[6])/pair.second);check(!manager.needs_memory(),"install granted active RAM access");manager.enable(pair.first,true);check(manager.needs_memory(),"enable lacks negotiated 12/14 mask");o.memory=MemorySnapshot{};manager.complete(o);o.memory->bytes[0]=8;o.memory->bytes[256]=10;manager.complete(o);manager.enable(pair.first,false);check(!manager.needs_memory()&&!manager.overlay().width,"disable left memory observer/HUD");manager.uninstall(pair.first);}}
 std::cout<<"SDK RAM checks="<<n<<" PASS\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
